//! The interception CA on disk: generating it, reporting an identity for it and removing it.
//!
//! The CA is an ECDSA P-256 key (PKCS#8 PEM) and a PEM certificate. CAs generated by earlier versions used an
//! RSA 2048 key (PKCS#1 PEM); those are still loaded, see `host_certs`. Installing the CA into the operating
//! system's trust store is the client's job, never the engine's.

use std::{
    io::Write,
    path::{Path, PathBuf},
};

use rand::Rng;
use rcgen::{
    BasicConstraints, CertificateParams, DistinguishedName, DnType, IsCa, KeyPair, KeyUsagePurpose, SerialNumber,
};
use sha1::Sha1;
use sha2::{Digest, Sha256};
use x509_parser::{certificate::X509Certificate, prelude::FromDer};

use crate::workspace::settings::app_data_dir;

const CA_CERT_FILE: &str = "ca-cert.pem";
const CA_KEY_FILE: &str = "ca-key.pem";
const CA_VALIDITY_DAYS: i64 = 3650;

/// The directory the CA files live in.
pub fn ca_dir() -> PathBuf {
    app_data_dir()
}

/// Where the engine keeps its own interception CA certificate.
pub fn ca_cert_path() -> PathBuf {
    app_data_dir().join(CA_CERT_FILE)
}

/// Where the engine keeps its own interception CA key.
pub fn ca_key_path() -> PathBuf {
    app_data_dir().join(CA_KEY_FILE)
}

/// What identifies a certificate to a person comparing it with what their operating system shows.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CertIdentity {
    /// `sha256:` + lowercase hex of the DER's SHA-256.
    pub fingerprint: String,
    /// Uppercase hex SHA-1 of the DER, no separators.
    pub thumbprint_sha1: String,
    /// The subject, one `KEY=value` per line in certificate order, as Node prints `X509Certificate.subject`.
    pub subject: String,
}

/// The first certificate of a PEM text as DER.
pub fn first_cert_der(pem: &str) -> Option<Vec<u8>> {
    use rustls::pki_types::{CertificateDer, pem::PemObject};
    CertificateDer::pem_slice_iter(pem.as_bytes()).find_map(|c| c.ok()).map(|c| c.as_ref().to_vec())
}

fn attribute_label(oid: &str) -> String {
    match oid {
        "2.5.4.3" => "CN",
        "2.5.4.6" => "C",
        "2.5.4.7" => "L",
        "2.5.4.8" => "ST",
        "2.5.4.9" => "street",
        "2.5.4.10" => "O",
        "2.5.4.11" => "OU",
        "2.5.4.5" => "serialNumber",
        "2.5.4.4" => "SN",
        "2.5.4.42" => "GN",
        "2.5.4.12" => "title",
        "1.2.840.113549.1.9.1" => "emailAddress",
        "0.9.2342.19200300.100.1.25" => "DC",
        other => other,
    }
    .to_string()
}

/// A distinguished name in Node's multi-line form.
pub fn format_subject(name: &x509_parser::x509::X509Name<'_>) -> String {
    let mut lines = Vec::new();
    for attr in name.iter_attributes() {
        let value = attr.as_str().map(str::to_string).unwrap_or_else(|_| hex::encode(attr.attr_value().data));
        lines.push(format!("{}={}", attribute_label(&attr.attr_type().to_id_string()), value));
    }
    lines.join("\n")
}

/// Identify a PEM certificate, or `None` when it cannot be parsed.
pub fn identify_cert(pem: &str) -> Option<CertIdentity> {
    let der = first_cert_der(pem)?;
    let (_, cert) = X509Certificate::from_der(&der).ok()?;
    Some(CertIdentity {
        fingerprint: format!("sha256:{}", hex::encode(Sha256::digest(&der))),
        thumbprint_sha1: hex::encode_upper(Sha1::digest(&der)),
        subject: format_subject(cert.subject()),
    })
}

/// The fingerprint of a PEM certificate.
pub fn fingerprint_of(pem: &str) -> Option<String> {
    identify_cert(pem).map(|identity| identity.fingerprint)
}

/// The files a generated CA was written to.
#[derive(Debug, Clone)]
pub struct GeneratedCa {
    pub cert_path: PathBuf,
    pub key_path: PathBuf,
    pub identity: CertIdentity,
}

/// A new ECDSA P-256 key.
pub fn generate_ca_key() -> Result<KeyPair, String> {
    KeyPair::generate_for(&rcgen::PKCS_ECDSA_P256_SHA256).map_err(|e| e.to_string())
}

/// The serial mkcert picks: the ASCII digits of a number between 50000 and 99999.
pub fn mkcert_serial() -> SerialNumber {
    let n: u32 = rand::rng().random_range(50000..145000);
    SerialNumber::from_slice(n.to_string().as_bytes())
}

/// The subject mkcert gives a CA, attributes in its order.
fn ca_subject() -> DistinguishedName {
    let mut dn = DistinguishedName::new();
    dn.push(DnType::CommonName, "Bifurc CA");
    dn.push(DnType::CountryName, "US");
    dn.push(DnType::StateOrProvinceName, "Development");
    dn.push(DnType::LocalityName, "Local");
    dn.push(DnType::OrganizationName, "Bifurc CA");
    dn
}

/// The CA certificate PEM and the key as PKCS#8 PEM for `key`, valid from now for ten years.
pub fn build_ca(key_pair: &KeyPair) -> Result<(String, String), String> {
    let mut params = CertificateParams::default();
    params.distinguished_name = ca_subject();
    params.is_ca = IsCa::Ca(BasicConstraints::Unconstrained);
    params.key_usages = vec![KeyUsagePurpose::KeyCertSign];
    params.serial_number = Some(mkcert_serial());
    let now = time::OffsetDateTime::now_utc();
    params.not_before = now;
    params.not_after = now + time::Duration::days(CA_VALIDITY_DAYS);
    let cert = params.self_signed(key_pair).map_err(|e| e.to_string())?;
    Ok((cert.pem(), key_pair.serialize_pem()))
}

/// Write a secret file readable by its owner only (where the platform has such a mode).
fn write_private(path: &Path, content: &str) -> std::io::Result<()> {
    let mut options = std::fs::OpenOptions::new();
    options.write(true).create(true).truncate(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    options.open(path)?.write_all(content.as_bytes())
}

/// Write a CA generated from `key` into `data_dir`.
pub fn write_ca(data_dir: &Path, key: &KeyPair) -> Result<GeneratedCa, String> {
    let (cert_pem, key_pem) = build_ca(key)?;
    let cert_path = data_dir.join(CA_CERT_FILE);
    let key_path = data_dir.join(CA_KEY_FILE);
    std::fs::create_dir_all(data_dir).map_err(|e| e.to_string())?;
    write_private(&cert_path, &cert_pem).map_err(|e| e.to_string())?;
    write_private(&key_path, &key_pem).map_err(|e| e.to_string())?;
    let identity = identify_cert(&cert_pem)
        .ok_or_else(|| "The generated CA certificate could not be parsed; refusing to report success.".to_string())?;
    Ok(GeneratedCa { cert_path, key_path, identity })
}

/// Generate a new CA into `data_dir`, replacing any existing one. Blocking; run it off the engine thread.
pub fn generate_ca(data_dir: &Path) -> Result<GeneratedCa, String> {
    write_ca(data_dir, &generate_ca_key()?)
}

/// Whether the CA files exist, and the certificate's fingerprint when it can be read.
pub fn get_cert_status(data_dir: &Path) -> (bool, Option<String>) {
    let (cert_path, key_path) = (data_dir.join(CA_CERT_FILE), data_dir.join(CA_KEY_FILE));
    if !cert_path.exists() || !key_path.exists() {
        return (false, None);
    }
    match std::fs::read_to_string(&cert_path) {
        Ok(pem) => (true, fingerprint_of(&pem)),
        Err(_) => (true, None),
    }
}

/// Delete the CA files. Best effort per file; `true` when at least one was removed.
pub fn remove_ca(data_dir: &Path) -> bool {
    let mut removed = false;
    for path in [data_dir.join(CA_CERT_FILE), data_dir.join(CA_KEY_FILE)] {
        if path.exists() && std::fs::remove_file(&path).is_ok() {
            removed = true;
        }
    }
    removed
}
